/* Pastel Dreams Theme - Auto-generated from tweakcn */

/* Light mode */
[data-theme="pastel-dreams-light"] {
  --background: rgb(248, 243, 250);
  --foreground: rgb(54, 64, 80);
  --card: rgb(255, 255, 255);
  --card-foreground: rgb(54, 64, 80);
  --popover: rgb(255, 255, 255);
  --popover-foreground: rgb(54, 64, 80);
  --primary: rgb(167, 139, 251);
  --primary-foreground: rgb(255, 255, 255);
  --secondary: rgb(233, 217, 252);
  --secondary-foreground: rgb(75, 86, 102);
  --muted: rgb(244, 234, 255);
  --muted-foreground: rgb(108, 114, 126);
  --accent: rgb(245, 229, 247);
  --accent-foreground: rgb(54, 64, 80);
  --destructive: rgb(251, 167, 167);
  --destructive-foreground: rgb(255, 255, 255);
  --border: rgb(233, 217, 252);
  --input: rgb(233, 217, 252);
  --ring: rgb(167, 139, 251);
  --chart-1: rgb(167, 139, 251);
  --chart-2: rgb(140, 93, 248);
  --chart-3: rgb(124, 56, 238);
  --chart-4: rgb(109, 41, 216);
  --chart-5: rgb(90, 32, 181);
  --radius: 1.5rem;
  --sidebar: rgb(233, 217, 252);
  --sidebar-foreground: rgb(54, 64, 80);
  --sidebar-primary: rgb(167, 139, 251);
  --sidebar-primary-foreground: rgb(255, 255, 255);
  --sidebar-accent: rgb(245, 229, 247);
  --sidebar-accent-foreground: rgb(54, 64, 80);
  --sidebar-border: rgb(233, 217, 252);
  --sidebar-ring: rgb(167, 139, 251);
  --font-sans: Open Sans, sans-serif;
  --font-serif: Source Serif 4, serif;
  --font-mono: IBM Plex Mono, monospace;
  --shadow-color: rgb(0, 0, 0);
  --shadow-opacity: 0.08;
  --shadow-blur: 16px;
  --shadow-spread: -4px;
  --shadow-offset-x: 0px;
  --shadow-offset-y: 8px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 0px 8px 16px -4px hsl(0 0% 0% / 0.04);
  --shadow-xs: 0px 8px 16px -4px hsl(0 0% 0% / 0.04);
  --shadow-sm:
    0px 8px 16px -4px hsl(0 0% 0% / 0.08), 0px 1px 2px -5px hsl(0 0% 0% / 0.08);
  --shadow:
    0px 8px 16px -4px hsl(0 0% 0% / 0.08), 0px 1px 2px -5px hsl(0 0% 0% / 0.08);
  --shadow-md:
    0px 8px 16px -4px hsl(0 0% 0% / 0.08), 0px 2px 4px -5px hsl(0 0% 0% / 0.08);
  --shadow-lg:
    0px 8px 16px -4px hsl(0 0% 0% / 0.08), 0px 4px 6px -5px hsl(0 0% 0% / 0.08);
  --shadow-xl:
    0px 8px 16px -4px hsl(0 0% 0% / 0.08), 0px 8px 10px -5px hsl(0 0% 0% / 0.08);
  --shadow-2xl: 0px 8px 16px -4px hsl(0 0% 0% / 0.2);
  --tracking-normal: 0em;
}

