  --foreground: rgb(225, 231, 253);
  --card: rgb(45, 37, 53);
  --card-foreground: rgb(225, 231, 253);
  --popover: rgb(45, 37, 53);
  --popover-foreground: rgb(225, 231, 253);
  --primary: rgb(193, 170, 255);
  --primary-foreground: rgb(30, 25, 22);
  --secondary: rgb(62, 50, 72);
  --secondary-foreground: rgb(208, 212, 219);
  --muted: rgb(45, 37, 53);
  --muted-foreground: rgb(155, 162, 174);
  --accent: rgb(75, 62, 91);
  --accent-foreground: rgb(208, 212, 219);
  --destructive: rgb(251, 167, 167);
  --destructive-foreground: rgb(30, 25, 22);
  --border: rgb(62, 50, 72);
  --input: rgb(62, 50, 72);
  --ring: rgb(193, 170, 255);
  --chart-1: rgb(193, 170, 255);
  --chart-2: rgb(167, 139, 251);
  --chart-3: rgb(140, 93, 248);
  --chart-4: rgb(124, 56, 238);
  --chart-5: rgb(109, 41, 216);
  --radius: 1.5rem;
  --sidebar: rgb(62, 50, 72);
  --sidebar-foreground: rgb(225, 231, 253);
  --sidebar-primary: rgb(193, 170, 255);
  --sidebar-primary-foreground: rgb(30, 25, 22);
  --sidebar-accent: rgb(75, 62, 91);
  --sidebar-accent-foreground: rgb(208, 212, 219);
  --sidebar-border: rgb(62, 50, 72);
  --sidebar-ring: rgb(193, 170, 255);
  --font-sans: Open Sans, sans-serif;
  --font-serif: Source Serif 4, serif;
  --font-mono: IBM Plex Mono, monospace;
  --shadow-color: rgb(0, 0, 0);
  --shadow-opacity: 0.08;
  --shadow-blur: 16px;
  --shadow-spread: -4px;
  --shadow-offset-x: 0px;
  --shadow-offset-y: 8px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 0px 8px 16px -4px hsl(0 0% 0% / 0.04);
  --shadow-xs: 0px 8px 16px -4px hsl(0 0% 0% / 0.04);
  --shadow-sm:
    0px 8px 16px -4px hsl(0 0% 0% / 0.08), 0px 1px 2px -5px hsl(0 0% 0% / 0.08);
  --shadow:
    0px 8px 16px -4px hsl(0 0% 0% / 0.08), 0px 1px 2px -5px hsl(0 0% 0% / 0.08);
  --shadow-md:
    0px 8px 16px -4px hsl(0 0% 0% / 0.08), 0px 2px 4px -5px hsl(0 0% 0% / 0.08);
  --shadow-lg:
    0px 8px 16px -4px hsl(0 0% 0% / 0.08), 0px 4px 6px -5px hsl(0 0% 0% / 0.08);
  --shadow-xl:
    0px 8px 16px -4px hsl(0 0% 0% / 0.08), 0px 8px 10px -5px hsl(0 0% 0% / 0.08);
  --shadow-2xl: 0px 8px 16px -4px hsl(0 0% 0% / 0.2);
}
